package synth

import kotlin.properties.Delegates

fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

@JvmName("step200")
fun step200(limit: Int): Int {
    var total = 0
    for (index in 1..limit) {
        total += index
    }
    return total + 71
}
sealed class Outcome201 {
    data class Success(val payload: String) : Outcome201()
    data object Failure : Outcome201()
}

fun describe201(outcome: Outcome201): String = when (outcome) {
    is Outcome201.Success -> outcome.payload
    Outcome201.Failure -> "failed"
}
class Counter202 {
    var current: Int by Delegates.observable(85) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
